mod tests {
    use super::*;
    use crate::api::client::MockApiClient;
    use crate::models::Project;
    use chrono::{TimeZone, Utc};

    fn entry(duration: i64, billable: bool, stop: bool, project: Option<&str>) -> TimeEntry {
        let start = Utc.timestamp_opt(1_700_000_000, 0).single().unwrap();
        TimeEntry {
            id: duration,
            description: String::new(),
            start,
            stop: stop.then_some(start),
            duration: if stop { duration } else { -start.timestamp() },
            billable,
            workspace_id: 1,
            tags: vec![],
            project: project.map(|name| Project {
                id: 1,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: start,
                created_at: start,
                color: "#000000".to_string(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn rounds_each_entry_up() {
        assert_eq!(
            rounded_billable_seconds(&entry(7 * 60, true, true, None)),
            Some(15 * 60)
        );
        assert_eq!(
            rounded_billable_seconds(&entry(22 * 60, true, true, None)),
            Some(30 * 60)
        );
        assert_eq!(
            rounded_billable_seconds(&entry(7 * 60, false, true, None)),
            None
        );
        assert_eq!(
            rounded_billable_seconds(&entry(7 * 60, true, false, None)),
            None
        );
    }

    #[tokio::test]
    async fn fetches_filtered_full_entries() {
        let mut client = MockApiClient::new();
        client
            .expect_get_time_entries_filtered()
            .returning(|_, _| Ok(vec![entry(7 * 60, true, true, Some("Beta"))]));
        assert!(BillCommand::execute(client, None, None).await.is_ok());
    }
}
